/**
 * Whether a `private` project (and, transitively, everything in it) is
 * visible to `actor`. `org`/`public` projects are always visible. Membership
 * and lead status are looked up live, so changes take effect immediately.
 */
export async function canActorViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Throws `NotFoundError` when `actor` may not see `project` — a private
 * project must behave as if it does not exist, not as a permission error. */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
  entity: string,
  id: string,
): Promise<void> {
  if (!(await canActorViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

/**
 * Private projects in the org that `actor` cannot see, for excluding an
 * org-wide listing's rows (and its `total`) from private projects the actor
 * has no access to.
 */
export async function hiddenPrivateProjectIds(
  actor: Actor,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff || hasRoleAtLeast(actor.role, "admin")) return [];

  const privateProjects = await projectRepo.listPrivateProjectLeads(
    actor.orgId,
  );
  const memberProjectIds = new Set(
    await projectMemberRepo.listMemberProjectIds(actor.orgId, actor.userId),
  );

  return privateProjects
    .filter(
      (p) => p.leadId !== actor.userId && !memberProjectIds.has(p.id),
    )
    .map((p) => p.id);
}

